const webhook = $('Webhook: Discover Nearby').first().json;
const body = webhook.body ?? webhook;

const geocode = $('Google: Geocode Address').first().json;

const radiusMiles = Number(body.radius_miles ?? 3);
const searchTerm = body.search_term || 'restaurant';

if (!Number.isFinite(radiusMiles) || radiusMiles <= 0) {
  throw new Error('radius_miles must be greater than 0');
}

// Prefer coordinates returned by Google Geocoding.
// Fall back to latitude/longitude supplied directly in the webhook.
let latitude;
let longitude;

if (
  geocode.status === 'OK' &&
  Array.isArray(geocode.results) &&
  geocode.results.length > 0
) {
  latitude = Number(geocode.results[0].geometry?.location?.lat);
  longitude = Number(geocode.results[0].geometry?.location?.lng);
} else {
  latitude = Number(body.latitude);
  longitude = Number(body.longitude);
}

if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
  throw new Error(
    'Could not resolve the business location. Provide a valid address or latitude/longitude.'
  );
}

const radiusKm = radiusMiles * 1.60934;

return [
  {
    json: {
      business_name: body.business_name ?? null,
      address: body.address ?? null,
      latitude,
      longitude,
      radius_miles: radiusMiles,

      apify_input: {
        searchStringsArray: [searchTerm],
        customGeolocation: {
          type: 'Point',
          coordinates: [
            longitude,
            latitude
          ],
          radiusKm
        },
        maxCrawledPlacesPerSearch: 12,
        language: 'en'
      }
    }
  }
];

const places = $input.all().map(item => item.json);

const build = $('Build Apify Input').first().json;
const webhook = $('Webhook: Discover Nearby').first().json;
const body = webhook.body ?? webhook;

const centerLat = Number(build.latitude);
const centerLng = Number(build.longitude);
const radiusMiles = Number(build.radius_miles ?? 3);

const businessName = String(body.business_name ?? '').trim().toLowerCase();
const searchTerm = String(body.search_term ?? 'restaurant').trim().toLowerCase();

function haversineMiles(lat1, lon1, lat2, lon2) {
  const R = 3958.8;
  const toRad = deg => deg * Math.PI / 180;

  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) *
      Math.cos(toRad(lat2)) *
      Math.sin(dLon / 2) ** 2;

  return 2 * R * Math.asin(Math.sqrt(a));
}

function cleanText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isMonitorableWebsite(value) {
  if (!value) return false;

  const raw = String(value).trim().toLowerCase();

  if (!/^https?:\/\//.test(raw)) {
    return false;
  }

  const host = raw
    .replace(/^https?:\/\//, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .replace(/^www\./, '');

  if (!host) return false;

  const blockedHosts = [
    'instagram.com',
    'facebook.com',
    'fb.com',
    'tiktok.com',
    'twitter.com',
    'x.com',
  ];

  return !blockedHosts.some(
    blocked => host === blocked || host.endsWith(`.${blocked}`)
  );
}

// Generic words should not make something look highly relevant.
// Example: "seafood restaurant" should not rank highly just because
// the search was "taco restaurant".
const STOPWORDS = new Set([
  'restaurant',
  'restaurants',
  'shop',
  'store',
  'business',
  'nearby',
  'local',
  'the',
  'and',
  'food',
]);

// Small semantic families for our current/future local-business wedges.
// This is intentionally deterministic — no extra AI call or API cost.
const KEYWORD_FAMILIES = [
  [
    'taco', 'tacos', 'taqueria', 'taquerias',
    'mexican', 'tex-mex', 'tex mex',
    'burrito', 'burritos', 'tortilla'
  ],
  [
    'pizza', 'pizzeria', 'pizzerias', 'italian'
  ],
  [
    'burger', 'burgers', 'hamburger', 'hamburgers'
  ],
  [
    'coffee', 'cafe', 'café', 'espresso', 'roastery'
  ],
  [
    'bakery', 'bakeries', 'pastry', 'pastries'
  ],
  [
    'salon', 'hair', 'beauty', 'barber', 'barbershop'
  ],
  [
    'gym', 'fitness', 'crossfit', 'pilates', 'yoga'
  ],
  [
    'bookstore', 'books', 'bookshop', 'comics'
  ],
];

const queryTokens = cleanText(searchTerm)
  .split(' ')
  .filter(token => token && !STOPWORDS.has(token));

const expandedTerms = new Set(queryTokens);

for (const family of KEYWORD_FAMILIES) {
  const familyMatchesQuery = family.some(term =>
    queryTokens.some(token =>
      cleanText(term).includes(token) ||
      token.includes(cleanText(term))
    )
  );

  if (familyMatchesQuery) {
    family.forEach(term => expandedTerms.add(cleanText(term)));
  }
}

function relevanceScore(place, distanceMiles) {
  const title = cleanText(place.title);
  const category = cleanText(place.categoryName);
  const combined = `${title} ${category}`;

  let score = 0;

  // Exact search phrase is strongest.
  if (combined.includes(cleanText(searchTerm))) {
    score += 8;
  }

  // Direct important query terms.
  for (const token of queryTokens) {
    if (title.includes(token)) score += 5;
    if (category.includes(token)) score += 4;
  }

  // Related semantic terms, e.g. taco → Mexican / taqueria / burrito.
  for (const term of expandedTerms) {
    if (queryTokens.includes(term)) continue;

    if (title.includes(term)) score += 3;
    if (category.includes(term)) score += 2.5;
  }

  // Distance matters, but it should not overpower semantic relevance.
  if (Number.isFinite(distanceMiles) && radiusMiles > 0) {
    const distanceRatio = Math.min(distanceMiles / radiusMiles, 1);
    score += (1 - distanceRatio) * 2;
  }

  // Very small quality tie-breakers.
  const rating = Number(place.totalScore);
  if (Number.isFinite(rating)) {
    score += Math.max(0, rating - 3.5) * 0.25;
  }

  const reviews = Number(place.reviewsCount ?? 0);
  if (reviews > 0) {
    score += Math.min(Math.log10(reviews + 1), 3) * 0.15;
  }

  return score;
}

const normalized = places
  .filter(place => {
    if (place.permanentlyClosed === true) return false;
    if (place.temporarilyClosed === true) return false;

    const name = cleanText(place.title);

    // Don't recommend the customer's own business.
    if (businessName && name === cleanText(businessName)) return false;

    return true;
  })
  .map(place => {
    const lat = Number(place.location?.lat);
    const lng = Number(place.location?.lng);

    const hasCoordinates =
      Number.isFinite(lat) &&
      Number.isFinite(lng) &&
      Number.isFinite(centerLat) &&
      Number.isFinite(centerLng);

    const distanceMiles = hasCoordinates
      ? haversineMiles(centerLat, centerLng, lat, lng)
      : null;

    return {
      name: place.title ?? 'Unknown business',
      category: place.categoryName ?? null,
      address: place.address ?? null,
      neighborhood: place.neighborhood ?? null,
      website: place.website ?? null,
      google_maps_url: place.url ?? null,
      latitude: Number.isFinite(lat) ? lat : null,
      longitude: Number.isFinite(lng) ? lng : null,
      distance_miles:
        distanceMiles === null
          ? null
          : Number(distanceMiles.toFixed(2)),
      rating:
        Number.isFinite(Number(place.totalScore))
          ? Number(place.totalScore)
          : null,
      reviews_count: Number(place.reviewsCount ?? 0),
      price: place.price ?? null,
      image_url: place.imageUrl ?? null,
      opening_hours: Array.isArray(place.openingHours)
        ? place.openingHours
        : [],
      place_id: place.placeId ?? null,
      can_monitor: isMonitorableWebsite(place.website),

      // Internal only — removed before response.
      _relevance_score: relevanceScore(place, distanceMiles),
    };
  })
  // Keep the search radius honest.
  .filter(place =>
    place.distance_miles === null ||
    place.distance_miles <= radiusMiles
  )
  .sort((a, b) => {
    // Relevance first.
    if (b._relevance_score !== a._relevance_score) {
      return b._relevance_score - a._relevance_score;
    }

    // Distance second.
    return (
      (a.distance_miles ?? Infinity) -
      (b.distance_miles ?? Infinity)
    );
  });

// Prefer genuinely relevant results.
//
// If we have enough strong matches, weak geographic-only matches disappear.
// If the area is sparse, fall back to the highest-ranked results instead
// of returning an empty discovery screen.
const strongMatches = normalized.filter(
  place => place._relevance_score >= 2.5
);

const selected =
  strongMatches.length >= 5
    ? strongMatches.slice(0, 8)
    : normalized.slice(0, 8);

const competitors = selected.map(({ _relevance_score, ...place }) => place);

return [
  {
    json: {
      business_name: build.business_name ?? body.business_name ?? null,
      radius_miles: radiusMiles,
      count: competitors.length,
      competitors,
    },
  },
];
